const input = $input.first().json;
const errors = [];
if (!input.slug || typeof input.slug !== 'string') errors.push('slug is required');
if (!input.title || typeof input.title !== 'string') errors.push('title is required');
if (!input.hook || typeof input.hook !== 'string') errors.push('hook is required (the single strongest factual line from the post)');
if (!input.url || typeof input.url !== 'string' || !input.url.startsWith('https://thecrawli.com/blog/')) errors.push('url is required and must be a https://thecrawli.com/blog/... link');
if (input.imageUrl && typeof input.imageUrl !== 'string') errors.push('imageUrl must be a string when provided');
if (errors.length) {
  throw new Error('threads auto post: invalid input - ' + errors.join('; '));
}
return [{ json: {
  slug: input.slug,
  title: input.title,
  hook: input.hook,
  url: input.url,
  imageUrl: input.imageUrl || null
} }];

const draftOut = $input.first().json;
const prior = $('Validate input').first().json;
let text = '';
try {
  text = draftOut.output[0].content[0].text.trim();
} catch (e) {
  throw new Error('threads auto post: could not read OpenAI output at output[0].content[0].text');
}
// Strip accidental code fences or a wrapping pair of quotes the model sometimes adds.
text = text.replace(/^```[a-z]*\n?/i, '').replace(/```$/, '').trim();
if (text.startsWith('"') && text.endsWith('"')) text = text.slice(1, -1).trim();

// Defensive net: make sure the link survives even if the model dropped it, and
// hard-enforce Threads' 500-char cap (we prompt for 450 but never trust an LLM
// for a hard limit).
if (!text.includes(prior.url)) {
  text = text + '\n\n' + prior.url;
}
if (text.length > 500) {
  const room = 500 - (prior.url.length + 2);
  text = text.slice(0, Math.max(0, room)).trim() + '\n\n' + prior.url;
}

return [{ json: { ...prior, caption: text } }];

const input = $input.first().json;
const THREADS_ACCOUNT_ID = '6a4c55359d9472faae9f8bea'; // thecrawli - fetched live via GET /v1/accounts on 2026-07-06, per docs/AGENT_PLAN.md §1A: Zernio account IDs are NOT stable across reconnects, re-check if this ever 403s.

const payload = {
  content: input.caption,
  platforms: [
    { platform: 'threads', accountId: THREADS_ACCOUNT_ID }
  ],
  publishNow: true
};
if (input.imageUrl) {
  payload.mediaItems = [{ type: 'image', url: input.imageUrl }];
}

return [{ json: payload }];

const resp = $input.first().json;
return [{ json: {
  postId: resp._id || resp.post?._id || null,
  status: resp.status || 'published',
  caption: $('Finalize caption').first().json.caption,
  raw: resp
} }];

// Best-effort dedup ledger, same content_history table TikTok content already
// uses (kind/title/topic_key/posted columns). Builds the row here; the actual
// HTTP call happens in the next node via a proper n8n credential, never a
// hardcoded key in this Code node.
const result = $input.first().json;
const prior = $('Validate input').first().json;
return [{ json: { ...result, _logRow: { kind: 'threads', title: prior.title, topic_key: prior.slug, posted: true } } }];
